 @Test public void geminiNativeWindowClosesWithoutStoppingItsRun()throws Exception{
  TermuxActivity a=activity();WorkspaceStore.Session selected=profile();selected.aiAgent="";selected.geminiAgent=true;java.util.List<String> operations=new java.util.concurrent.CopyOnWriteArrayList<>();
  AgentChatUi ui=new AgentChatUi(a,()->selected,()->true,(p,q)->{operations.add(q.optString("op"));return result().put("session",selected.geminiThread).put("connected",true);});
  try{for(int i=0;i<30&&!ui.showing();i++)drain();ui.terminal();android.app.AlertDialog dialog=null;for(int i=0;i<30;i++){drain();dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(dialog!=null&&dialog.isShowing())break;}assertNotNull(dialog);assertTrue(dialog.isShowing());assertFalse(hasText(dialog.getWindow().getDecorView(),"Esc"));assertEquals("Enter",dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).getText().toString());dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(dialog.isShowing());dialog.getButton(android.app.AlertDialog.BUTTON_NEUTRAL).performClick();for(int i=0;i<20&&!operations.contains("terminal-close");i++)drain();assertTrue(operations.contains("terminal-open"));assertTrue(operations.contains("terminal-close"));assertFalse(operations.contains("stop"));assertTrue(ui.showing());}finally{ui.close();}
 }

 @Test public void geminiResumeDropsOldAcknowledgementAndUsesNewSessionToken()throws Exception{
  TermuxActivity a=activity();WorkspaceStore.Session selected=profile();selected.aiAgent="";selected.geminiAgent=true;AtomicReference<String> token=new AtomicReference<>(selected.geminiThread);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger accepted=new AtomicInteger();java.util.List<String> ids=new java.util.concurrent.CopyOnWriteArrayList<>();
  AgentChatUi ui=new AgentChatUi(a,()->selected,()->true,(p,q)->{if(q.optString("op").equals("chat-send")){ids.add(q.optString("id"));if(q.optString("session").equals(selected.geminiThread)){entered.countDown();release.await(3,TimeUnit.SECONDS);}else assertEquals(token.get(),q.optString("session"));return new JSONObject().put("ok",true).put("accepted",true);}return result().put("session",token.get()).put("connected",true);});
  try{for(int i=0;i<30&&!ui.showing();i++)drain();ui.send("same draft",accepted::incrementAndGet);assertTrue(entered.await(2,TimeUnit.SECONDS));token.set(java.util.UUID.randomUUID().toString());Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(2));for(int i=0;i<10;i++)drain();release.countDown();for(int i=0;i<10;i++)drain();assertEquals(0,accepted.get());ui.send("same draft",accepted::incrementAndGet);for(int i=0;i<30&&accepted.get()==0;i++)drain();assertEquals(1,accepted.get());assertEquals(2,ids.size());assertNotEquals(ids.get(0),ids.get(1));}finally{release.countDown();ui.close();}
 }

