 @Test public void rejectedSendNoticeSurvivesPollingAndDoesNotResendAutomatically()throws Exception{
  TermuxActivity a=activity();WorkspaceStore.Session selected=profile();AtomicBoolean reject=new AtomicBoolean(true);AtomicInteger sends=new AtomicInteger(),ack=new AtomicInteger();
  AgentChatUi ui=new AgentChatUi(a,()->selected,()->true,(p,q)->{if(q.optString("op").equals("chat-send")){sends.incrementAndGet();if(reject.get())throw new java.io.IOException("not ready");return new JSONObject().put("ok",true).put("accepted",true);}return result().put("connected",true);});
  try{for(int i=0;i<30&&!ui.showing();i++)drain();FrameLayout host=a.findViewById(R.id.workspace_terminal_surface);AgentChatView chat=(AgentChatView)host.getChildAt(host.getChildCount()-1);ui.send("draft",ack::incrementAndGet);for(int i=0;i<30&&!chat.connection.getText().toString().contains("не подтверждена")&&!chat.connection.getText().toString().contains("Delivery unconfirmed");i++)drain();String notice=chat.connection.getText().toString();assertTrue(notice.contains("не подтверждена")||notice.contains("Delivery unconfirmed"));Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(3));for(int i=0;i<8;i++)drain();assertEquals(notice,chat.connection.getText().toString());assertEquals(1,sends.get());assertEquals(0,ack.get());reject.set(false);ui.send("draft",ack::incrementAndGet);for(int i=0;i<30&&ack.get()==0;i++)drain();assertEquals(2,sends.get());assertEquals(1,ack.get());}finally{ui.close();}
 }

