 @Test public void refusalAndUnconfirmedDeliveryKeepAttachmentsForEveryAgent()throws Exception{
  for(String agent:new String[]{"codex","gemini","claude","opencode"})for(String delivery:new String[]{"rejected","unconfirmed"}){
   TermuxActivity a=activity();WorkspaceStore.Session p=profile();p.aiAgent=agent.equals("opencode")?agent:"";p.geminiAgent=agent.equals("gemini");p.claudeAgent=agent.equals("claude");p.environment=agent.equals("codex")?"codex":"ubuntu";p.codexEnvironment="ubuntu-ai";
   java.io.File marker=null;if(agent.equals("codex")){marker=CodexChatControl.marker(a.getFilesDir(),p);marker.getParentFile().mkdirs();marker.createNewFile();}
   AtomicInteger ack=new AtomicInteger(),sends=new AtomicInteger();AgentChatUi ui=new AgentChatUi(a,()->p,()->true,(profile,q)->{if(q.optString("op").equals("chat-send")){sends.incrementAndGet();return new JSONObject().put("ok",false).put("delivery",delivery);}return result().put("session","owned-refusal-"+agent).put("connected",true).put("attachmentsSupported",true);});
   try{for(int n=0;n<40&&!ui.showing();n++)drain();assertTrue(agent,ui.showing());Field field=AgentChatUi.class.getDeclaredField("attachments");field.setAccessible(true);ChatAttachmentUi manager=(ChatAttachmentUi)field.get(ui);Field owner=ChatAttachmentUi.class.getDeclaredField("owner");owner.setAccessible(true);Field drafts=ChatAttachmentUi.class.getDeclaredField("drafts");drafts.setAccessible(true);java.util.Map<String,java.util.List<JSONObject>> map=(java.util.Map<String,java.util.List<JSONObject>>)drafts.get(manager);map.put((String)owner.get(manager),new java.util.ArrayList<>(java.util.Arrays.asList(new JSONObject().put("id","eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee").put("type","binary").put("name","kept.zip"))));
    ui.send("kept text",ack::incrementAndGet);for(int n=0;n<8;n++)drain();assertEquals(agent,1,sends.get());assertEquals(agent,0,ack.get());assertTrue(agent,ui.hasAttachments());
    FrameLayout host=a.findViewById(R.id.workspace_terminal_surface);AgentChatView chat=(AgentChatView)host.getChildAt(host.getChildCount()-1);assertTrue(chat.connection.getText().length()>0);
   }finally{ui.close();if(marker!=null)marker.delete();}
  }
 }

 @Test public void codexQuestionUsesItsReplyChannelWhileSendIsStillPendingAndKeepsDraftOnFailure()throws Exception{
  TermuxActivity a=activity();WorkspaceStore.Session p=profile();p.aiAgent="";p.environment="codex";p.codexEnvironment="ubuntu-ai";java.io.File marker=CodexChatControl.marker(a.getFilesDir(),p);marker.getParentFile().mkdirs();marker.createNewFile();AtomicReference<WorkspaceStore.Session> selected=new AtomicReference<>(p);
  AtomicInteger replies=new AtomicInteger();AtomicBoolean pending=new AtomicBoolean(true);CountDownLatch sending=new CountDownLatch(1),release=new CountDownLatch(1),replyEntered=new CountDownLatch(1),replyRelease=new CountDownLatch(1);
  JSONObject form=new JSONObject().put("id","question-owned").put("nonce","native-nonce").put("title","Question").put("fields",new JSONArray().put(new JSONObject().put("key","choice").put("title","Choose carefully").put("type","string").put("custom",true).put("options",new JSONArray().put(new JSONObject().put("label","First").put("value","A")).put(new JSONObject().put("label","Second").put("value","B")))));
  AgentChatUi ui=new AgentChatUi(a,selected::get,()->true,(profile,q)->{
   if(q.optString("op").equals("chat-send")){sending.countDown();release.await(4,TimeUnit.SECONDS);return new JSONObject().put("ok",true).put("accepted",true);}
   if(q.optString("op").equals("chat-form")){assertEquals("owned-session",q.optString("session"));assertEquals("question-owned",q.optString("id"));assertEquals("native-nonce",q.optString("nonce"));assertEquals("custom exact answer",q.getJSONObject("answer").getString("choice"));if(replies.incrementAndGet()==1){replyEntered.countDown();replyRelease.await(4,TimeUnit.SECONDS);return new JSONObject().put("ok",false).put("error","FORM_UNCONFIRMED");}pending.set(false);return new JSONObject().put("ok",true).put("accepted",true);}
   return result().put("session","owned-session").put("connected",true).put("busy",true).put("forms",pending.get()?new JSONArray().put(form):new JSONArray());
  });
  try{for(int n=0;n<40&&!ui.showing();n++)drain();FrameLayout host=a.findViewById(R.id.workspace_terminal_surface);AgentChatView chat=(AgentChatView)host.getChildAt(host.getChildCount()-1);android.view.View card=chat.requests.findViewWithTag("codex-question-question-owned");assertNotNull(card);android.widget.RadioButton option=card.findViewWithTag("question-option-choice-0");assertFalse(option.isChecked());card.findViewWithTag("question-send").performClick();drain();assertEquals(0,replies.get());
   ((android.widget.RadioButton)card.findViewWithTag("question-option-choice-1")).performClick();android.widget.EditText custom=card.findViewWithTag("question-custom-choice");custom.setText("custom exact answer");assertFalse(option.isChecked());
   selected.set(new WorkspaceStore.Session());ui.sync();selected.set(p);ui.sync();reload(ui);for(int n=0;n<20;n++)drain();card=chat.requests.findViewWithTag("codex-question-question-owned");assertEquals("custom exact answer",((android.widget.EditText)card.findViewWithTag("question-custom-choice")).getText().toString());
   ui.send("held request",()->{});assertTrue(sending.await(2,TimeUnit.SECONDS));card.findViewWithTag("question-send").performClick();for(int n=0;n<30&&replies.get()==0;n++)drain();assertEquals("question reply must not wait for send executor",1,replies.get());assertTrue(replyEntered.await(1,TimeUnit.SECONDS));selected.set(new WorkspaceStore.Session());ui.sync();selected.set(p);ui.sync();replyRelease.countDown();for(int n=0;n<8;n++)drain();reload(ui);card=chat.requests.findViewWithTag("codex-question-question-owned");assertNotNull(card);assertEquals("custom exact answer",((android.widget.EditText)card.findViewWithTag("question-custom-choice")).getText().toString());assertTrue(card.findViewWithTag("question-send").isEnabled());
   card.findViewWithTag("question-send").performClick();for(int n=0;n<30&&replies.get()<2;n++)drain();assertEquals(2,replies.get());reload(ui);card.findViewWithTag("question-send").performClick();drain();assertEquals("late button cannot answer a different question",2,replies.get());
  }finally{replyRelease.countDown();release.countDown();ui.close();marker.delete();}
 }

 private CodexActionsView timelineCard(AgentChatView chat){for(int i=0;i<chat.timeline.getChildCount();i++)if(chat.timeline.getChildAt(i)instanceof CodexActionsView)return(CodexActionsView)chat.timeline.getChildAt(i);return null;}
 private void awaitTimeline(AgentChatView chat)throws Exception{for(int i=0;i<40&&timelineCard(chat)==null;i++){Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(250));drain();}assertNotNull("Scheduled native snapshot must arrive",timelineCard(chat));}
 private void layoutTimeline(AgentChatView chat){for(int i=0;i<3;i++){android.view.View host=(android.view.View)chat.getParent();host.measure(android.view.View.MeasureSpec.makeMeasureSpec(400,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(500,android.view.View.MeasureSpec.EXACTLY));host.layout(0,0,400,500);chat.scroll.getViewTreeObserver().dispatchOnPreDraw();Shadows.shadowOf(Looper.getMainLooper()).idle();}}
 private void readTimelineAt(AgentChatView chat,int y){long t=android.os.SystemClock.uptimeMillis();for(int action:new int[]{android.view.MotionEvent.ACTION_DOWN,android.view.MotionEvent.ACTION_CANCEL}){android.view.MotionEvent e=android.view.MotionEvent.obtain(t,t,action,10,10,0);chat.scroll.dispatchTouchEvent(e);e.recycle();if(action==android.view.MotionEvent.ACTION_DOWN)chat.scroll.scrollTo(0,y);}}
 @Test public void timelineChoiceFollowsEachAgentThroughControllerSwitchOlderPageAndWindowReopen()throws Exception{
  for(String agent:new String[]{"codex","claude","gemini","opencode"}){
   TermuxActivity a=activity();WorkspaceStore.Session first=profile();first.environment=agent.equals("codex")?"codex":"ubuntu";first.codexEnvironment="ubuntu-ai";first.aiAgent=agent.equals("opencode")?agent:"";first.claudeAgent=agent.equals("claude");first.geminiAgent=agent.equals("gemini");WorkspaceStore.Session second=first.copy();second.id="separate-"+agent;
   java.io.File marker=CodexChatControl.marker(a.getFilesDir(),first),peer=CodexChatControl.marker(a.getFilesDir(),second);marker.getParentFile().mkdirs();marker.createNewFile();peer.getParentFile().mkdirs();peer.createNewFile();AtomicReference<WorkspaceStore.Session> selected=new AtomicReference<>(first);AtomicBoolean visible=new AtomicBoolean(true);AtomicInteger modelOps=new AtomicInteger(),previous=new AtomicInteger();
   AgentChatUi ui=new AgentChatUi(a,selected::get,visible::get,(p,q)->{
    if(q.optString("op").equals("chat-send")||q.optString("op").contains("compact")){modelOps.incrementAndGet();throw new AssertionError("Timeline must not invoke the model");}
    boolean old=q.has("cursor");if(old)previous.incrementAndGet();JSONArray rows=new JSONArray();if(old)rows.put(new JSONObject().put("key","earlier").put("message","earlier").put("kind","text").put("body","older native message"));else{
     for(int n=0;n<25;n++)rows.put(new JSONObject().put("key","m"+n).put("message","m"+n).put("kind","text").put("body","Synthetic history "+n+"\nsecond line\nthird line"));
     rows.put(new JSONObject().put("key","read").put("message","read").put("kind","tool").put("toolName","Read").put("toolPath","/synthetic/Native.java").put("status","completed").put("body","native event"));rows.put(new JSONObject().put("key","cmd").put("message","cmd").put("kind","tool").put("actionType","shell").put("command","synthetic command").put("status","running").put("body","native output"));}
    return result().put("connected",true).put("session",p.id).put("rows",rows).put("partialHistory",true).put("older",old?JSONObject.NULL:"previous");
   });
   try{
    ui.sync();AgentChatView chat=org.robolectric.util.ReflectionHelpers.getField(ui,"view");awaitTimeline(chat);CodexActionsView card=timelineCard(chat);assertNotNull(agent,card);assertEquals(agent,2,card.steps.getChildCount());assertEquals(android.view.View.GONE,card.steps.getVisibility());card.heading.performClick();layoutTimeline(chat);readTimelineAt(chat,200);AgentChatView.Position firstPosition=chat.position();assertFalse(agent+" timeline="+chat.timeline.getHeight()+" viewport="+chat.scroll.getHeight()+" y="+chat.scroll.getScrollY()+" anchor="+firstPosition.anchor,firstPosition.bottom);
    selected.set(second);ui.sync();awaitTimeline(chat);assertEquals("The other chat starts collapsed",android.view.View.GONE,timelineCard(chat).steps.getVisibility());layoutTimeline(chat);readTimelineAt(chat,400);AgentChatView.Position secondPosition=chat.position();assertFalse(secondPosition.bottom);assertNotEquals(firstPosition.y,secondPosition.y);
    selected.set(first);ui.sync();awaitTimeline(chat);layoutTimeline(chat);card=timelineCard(chat);assertEquals(agent,android.view.View.VISIBLE,card.steps.getVisibility());assertEquals(firstPosition.anchor,chat.position().anchor);assertEquals(firstPosition.offset,chat.position().offset);
    chat.older.performClick();for(int i=0;i<60&&previous.get()==0;i++)drain();for(int i=0;i<20&&!hasText(chat,(agent.equals("codex")?"Codex":agent.equals("claude")?"Claude":agent.equals("gemini")?"Gemini":"OpenCode")+": older native message");i++)drain();layoutTimeline(chat);assertEquals(firstPosition.anchor,chat.position().anchor);assertEquals(firstPosition.offset,chat.position().offset);card=timelineCard(chat);assertEquals(android.view.View.VISIBLE,card.steps.getVisibility());card.heading.performClick();visible.set(false);ui.sync();visible.set(true);ui.sync();awaitTimeline(chat);assertEquals(android.view.View.GONE,timelineCard(chat).steps.getVisibility());
    selected.set(second);ui.sync();awaitTimeline(chat);layoutTimeline(chat);assertEquals(secondPosition.anchor,chat.position().anchor);assertEquals(secondPosition.offset,chat.position().offset);assertEquals(android.view.View.GONE,timelineCard(chat).steps.getVisibility());assertEquals(0,modelOps.get());
   }finally{ui.close();marker.delete();peer.delete();}
  }
 }

